-- CT Alt desktop Forms. Additive; no applied table/function is replaced.
create table public.forms(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,description text not null,schema jsonb not null default '[]',schema_frozen boolean not null default false,status text not null default 'draft'check(status in('draft','published','archived')),restore_status text check(restore_status in('draft','published')),allow_respondent_edit boolean not null default false,revision integer not null default 1 check(revision>0),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(tenant_id,id));
create table public.form_assignments(tenant_id uuid not null,form_id uuid not null,actor_id uuid not null,name text not null,primary key(tenant_id,form_id,actor_id),foreign key(tenant_id,form_id)references public.forms(tenant_id,id));
create table public.form_responses(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,form_id uuid not null,actor_id uuid not null,author_name text not null,status text not null default 'in_progress'check(status in('in_progress','submitted')),revision integer not null default 1 check(revision>0),answers jsonb not null default '{}',schema jsonb not null,form_name text not null,submitted_at timestamptz,updated_at timestamptz not null default clock_timestamp(),last_edited_by uuid not null,last_editor_name text not null,last_edited_at timestamptz not null default clock_timestamp(),reviewed boolean not null default false,reviewed_at timestamptz,reviewed_by uuid,reviewer_name text,content_edits integer not null default 0 check(content_edits between 0 and 50),unique(tenant_id,id),unique(tenant_id,form_id,actor_id),foreign key(tenant_id,form_id)references public.forms(tenant_id,id),check((status='submitted')=(submitted_at is not null)));
create table public.form_audit(id bigint generated always as identity primary key,tenant_id uuid not null,form_id uuid not null,response_id uuid,actor_id uuid not null,actor_name text not null,action text not null,form_revision integer not null,response_revision integer,occurred_at timestamptz not null default clock_timestamp(),foreign key(tenant_id,form_id)references public.forms(tenant_id,id),foreign key(tenant_id,response_id)references public.form_responses(tenant_id,id));
create table workforce_private.form_operations(tenant_id uuid not null,actor_id uuid not null,operation_id uuid not null,form_id uuid,response_id uuid,action text not null,state text not null default'recorded'check(state in('recorded','closed_absent')),payload_hash text,result jsonb,check((state='recorded'and form_id is not null and payload_hash is not null and payload_hash~'^[a-f0-9]{64}$'and result is not null and jsonb_typeof(result)='object')or(state='closed_absent'and form_id is null and response_id is null and payload_hash is null and result is null)),primary key(tenant_id,actor_id,operation_id),foreign key(tenant_id,form_id)references public.forms(tenant_id,id),foreign key(tenant_id,response_id)references public.form_responses(tenant_id,id));
create table workforce_private.form_response_history(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,response_id uuid not null,revision integer not null,answers jsonb not null,status text not null,submitted_at timestamptz not null,updated_at timestamptz not null,last_edited_by uuid not null,last_editor_name text not null,last_edited_at timestamptz not null default clock_timestamp(),reviewed boolean not null,reviewed_at timestamptz,reviewed_by uuid,reviewer_name text,retained_at timestamptz not null default clock_timestamp(),unique(tenant_id,response_id,revision),foreign key(tenant_id,response_id)references public.form_responses(tenant_id,id));
create table workforce_private.form_history_counter(id boolean primary key default true check(id),retained_rows integer not null default 0 check(retained_rows between 0 and 4096));insert into workforce_private.form_history_counter default values;
create index forms_catalog on public.forms(tenant_id,created_at desc,id desc);create index form_response_page on public.form_responses(tenant_id,form_id,submitted_at desc,id desc);create index form_response_history_page on workforce_private.form_response_history(tenant_id,response_id,revision desc);
alter table public.forms enable row level security;alter table public.form_assignments enable row level security;alter table public.form_responses enable row level security;alter table public.form_audit enable row level security;alter table workforce_private.form_operations enable row level security;alter table workforce_private.form_response_history enable row level security;alter table workforce_private.form_history_counter enable row level security;
revoke all on public.forms,public.form_assignments,public.form_responses,public.form_audit,workforce_private.form_operations,workforce_private.form_response_history,workforce_private.form_history_counter from public,anon,authenticated,service_role;grant select on public.forms,public.form_assignments,public.form_responses,public.form_audit to authenticated;
create function workforce_private.forms_reader(t uuid,f uuid)returns boolean language sql stable security definer set search_path=''as $$select workforce_private.membership_role(t)is not null and exists(select 1 from public.forms x join public.form_assignments a on a.tenant_id=x.tenant_id and a.form_id=x.id where x.tenant_id=t and x.id=f and x.status='published'and a.actor_id=(select auth.uid()))$$;
create function workforce_private.forms_access(t uuid,f uuid,mode text)returns boolean language sql stable security definer set search_path=''as $$select coalesce(case mode when'manage'then workforce_private.membership_role(t)in('owner','admin')and exists(select 1 from public.forms where tenant_id=t and id=f)when'mine'then workforce_private.forms_reader(t,f)else false end,false)$$;
create function workforce_private.forms_eligible(t uuid,u uuid)returns boolean language sql stable security definer set search_path=''as $$select workforce_private.membership_role(t)is not null and exists(select 1 from public.tenant_memberships m join public.tenants x on x.id=m.tenant_id join auth.users a on a.id=m.user_id where m.tenant_id=t and m.user_id=u and m.status='active'and x.status='active'and a.email_confirmed_at is not null and a.is_anonymous is not true)$$;
create policy forms_read on public.forms for select to authenticated using(workforce_private.membership_role(tenant_id)in('owner','admin')or workforce_private.forms_reader(tenant_id,id));
create policy form_assignment_read on public.form_assignments for select to authenticated using(workforce_private.membership_role(tenant_id)in('owner','admin')or actor_id=(select auth.uid())and workforce_private.forms_reader(tenant_id,form_id));
create policy form_response_read on public.form_responses for select to authenticated using((status='submitted'and workforce_private.membership_role(tenant_id)in('owner','admin'))or actor_id=(select auth.uid())and workforce_private.forms_reader(tenant_id,form_id));
create policy form_audit_read on public.form_audit for select to authenticated using(workforce_private.membership_role(tenant_id)in('owner','admin')and(response_id is null or exists(select 1 from public.form_responses r where r.tenant_id=form_audit.tenant_id and r.id=form_audit.response_id and r.status='submitted')));
-- The RPC takes raw JSON text, preserving duplicate keys before jsonb normalization.
create function workforce_private.forms_json_unique(v json,depth integer default 0)returns boolean language plpgsql immutable security invoker set search_path=''as $$declare item json;begin
 if depth>8 then return false;end if;
 if json_typeof(v)='object'then if exists(select 1 from json_each(v)group by key having count(*)>1)then return false;end if;for item in select value from json_each(v)loop if not workforce_private.forms_json_unique(item,depth+1)then return false;end if;end loop;
 elsif json_typeof(v)='array'then for item in select value from json_array_elements(v)loop if not workforce_private.forms_json_unique(item,depth+1)then return false;end if;end loop;end if;return true;end$$;
create function workforce_private.forms_schema_valid(s jsonb)returns boolean language plpgsql immutable security invoker set search_path=''as $$declare f jsonb;o jsonb;k text;begin
 if jsonb_typeof(s)is distinct from'array'or jsonb_array_length(s)>50 or octet_length(s::text)>131072 then return false;end if;
 if(select count(distinct lower(v->>'id'))from jsonb_array_elements(s)v)<>jsonb_array_length(s)then return false;end if;
 for f in select value from jsonb_array_elements(s)loop
  if jsonb_typeof(f)is distinct from'object'or not workforce_private.knowledge_uuid(f->'id')then return false;end if;k:=f->>'kind';
  if k='description'then if(select array_agg(key order by key)from jsonb_object_keys(f)key)is distinct from array['id','kind','text']or jsonb_typeof(f->'text')is distinct from'string'or workforce_private.knowledge_utf16(f->>'text')>5000 then return false;end if;
  elsif k in('text','yes_no','number','single_choice','multiple_choice')then
   if(select array_agg(key order by key)from jsonb_object_keys(f)key)is distinct from(case when k in('single_choice','multiple_choice')then array['id','kind','label','options','required']else array['id','kind','label','required']end)or jsonb_typeof(f->'label')is distinct from'string'or not workforce_private.knowledge_nonblank(f->>'label')or workforce_private.knowledge_utf16(f->>'label')>100 or jsonb_typeof(f->'required')is distinct from'boolean'then return false;end if;
   if k in('single_choice','multiple_choice')then if jsonb_typeof(f->'options')is distinct from'array'or jsonb_array_length(f->'options')not between 1 and 50 or(select count(distinct lower(v->>'id'))from jsonb_array_elements(f->'options')v)<>jsonb_array_length(f->'options')then return false;end if;for o in select value from jsonb_array_elements(f->'options')loop if jsonb_typeof(o)is distinct from'object'or(select array_agg(key order by key)from jsonb_object_keys(o)key)is distinct from array['id','label']or not workforce_private.knowledge_uuid(o->'id')or jsonb_typeof(o->'label')is distinct from'string'or not workforce_private.knowledge_nonblank(o->>'label')or workforce_private.knowledge_utf16(o->>'label')>100 then return false;end if;end loop;end if;
  else return false;end if;
 end loop;return true;
exception when others then return false;end$$;
create function workforce_private.forms_answers_valid(s jsonb,a jsonb,complete boolean)returns boolean language plpgsql immutable security invoker set search_path=''as $$declare f jsonb;v jsonb;k text;present boolean;begin
 if jsonb_typeof(a)is distinct from'object'or octet_length(a::text)>65536 or exists(select 1 from jsonb_each(a)e where not exists(select 1 from jsonb_array_elements(s)sf where sf->>'kind'<>'description'and sf->>'id'=e.key))then return false;end if;
 for f in select value from jsonb_array_elements(s)loop k:=f->>'kind';if k='description'then continue;end if;present:=a?(f->>'id');v:=a->(f->>'id');
  if not present then if complete and(f->>'required')::boolean then return false;end if;continue;end if;
  if k='text'then if jsonb_typeof(v)is distinct from'string'or workforce_private.knowledge_utf16(v#>>'{}')>5000 or complete and(f->>'required')::boolean and not workforce_private.knowledge_nonblank(v#>>'{}')then return false;end if;
  elsif k='yes_no'then if jsonb_typeof(v)is distinct from'boolean'then return false;end if;
  elsif k='number'then if jsonb_typeof(v)is distinct from'string'or workforce_private.knowledge_utf16(v#>>'{}')>32 or(case when complete then(v#>>'{}')!~'^[+-]?[0-9]{1,12}(\.[0-9]{1,6})?$'else(v#>>'{}')!~'^[+-]?[0-9]*(\.[0-9]*)?$'end)then return false;end if;if complete then perform(v#>>'{}')::numeric;end if;
  elsif k='single_choice'then if not workforce_private.knowledge_uuid(v)or not exists(select 1 from jsonb_array_elements(f->'options')o where o->>'id'=v#>>'{}')then return false;end if;
  elsif k='multiple_choice'then if jsonb_typeof(v)is distinct from'array'or jsonb_array_length(v)>50 or(select count(distinct e::text)from jsonb_array_elements(v)e)<>jsonb_array_length(v)or exists(select 1 from jsonb_array_elements(v)e where not workforce_private.knowledge_uuid(e)or not exists(select 1 from jsonb_array_elements(f->'options')o where o->>'id'=e#>>'{}'))or complete and(f->>'required')::boolean and jsonb_array_length(v)=0 then return false;end if;
  else return false;end if;
 end loop;return true;
exception when others then return false;end$$;
create function workforce_private.forms_name_valid(c jsonb)returns boolean language sql immutable security invoker set search_path=''as $$select jsonb_typeof(c->'name')='string'and workforce_private.knowledge_nonblank(c->>'name')and workforce_private.knowledge_utf16(c->>'name')<=100 and jsonb_typeof(c->'description')='string'and workforce_private.knowledge_utf16(c->>'description')<=500$$;
create function workforce_private.forms_audience_valid(t uuid,a jsonb)returns boolean language plpgsql stable security definer set search_path=''as $$begin return jsonb_typeof(a)='array'and jsonb_array_length(a)<=500 and(select count(distinct lower(v#>>'{}'))from jsonb_array_elements(a)v)=jsonb_array_length(a)and not exists(select 1 from jsonb_array_elements(a)v where not workforce_private.knowledge_uuid(v)or not workforce_private.forms_eligible(t,(v#>>'{}')::uuid));exception when others then return false;end$$;
create function workforce_private.forms_schema_canonical(s jsonb)returns jsonb language sql immutable security invoker set search_path=''as $$select coalesce(jsonb_agg(case when f->>'kind'in('single_choice','multiple_choice')then jsonb_set(jsonb_set(f,'{id}',to_jsonb(lower(f->>'id'))),'{options}',(select jsonb_agg(jsonb_set(o,'{id}',to_jsonb(lower(o->>'id')))order by n)from jsonb_array_elements(f->'options')with ordinality v(o,n)))else jsonb_set(f,'{id}',to_jsonb(lower(f->>'id')))end order by i),'[]'::jsonb)from jsonb_array_elements(s)with ordinality x(f,i)$$;
create function workforce_private.forms_answers_canonical(s jsonb,a jsonb)returns jsonb language plpgsql immutable security invoker set search_path=''as $$declare result jsonb:='{}';e record;f jsonb;v jsonb;begin
 if jsonb_typeof(a)is distinct from'object'or(select count(distinct lower(key))from jsonb_each(a))<>(select count(*)from jsonb_each(a))then raise exception using errcode='22023',message='Invalid answer identity';end if;
 for e in select key,value from jsonb_each(a)loop select value into f from jsonb_array_elements(s)where value->>'id'=lower(e.key);v:=e.value;
 if f->>'kind'='single_choice'and workforce_private.knowledge_uuid(v)then v:=to_jsonb(lower(v#>>'{}'));elsif f->>'kind'='multiple_choice'and jsonb_typeof(v)='array'then select coalesce(jsonb_agg(case when workforce_private.knowledge_uuid(value)then to_jsonb(lower(value#>>'{}'))else value end),'[]'::jsonb)into v from jsonb_array_elements(v);end if;
 result:=result||jsonb_build_object(lower(e.key),v);end loop;return result;end$$;
create function workforce_private.forms_lock_audience(t uuid,a jsonb)returns void language plpgsql security definer set search_path=''as $$begin
 perform 1 from public.tenant_memberships m join auth.users u on u.id=m.user_id where m.tenant_id=t and m.user_id in(select(value#>>'{}')::uuid from jsonb_array_elements(a))order by m.user_id for share of m,u;end$$;
create function workforce_private.forms_locks(t uuid,a uuid,o uuid,history boolean default false)returns void language plpgsql security definer set search_path=''as $$begin perform pg_advisory_xact_lock(hashtextextended(a::text||':'||o::text,63));perform pg_advisory_xact_lock(hashtextextended(t::text,64));if history then perform pg_advisory_xact_lock(hashtextextended('forms-history',65));perform 1 from workforce_private.form_history_counter where form_history_counter.id for update;end if;end$$;
create function workforce_private.save_form(t uuid,o uuid,raw_change text)returns jsonb language plpgsql security definer set search_path=''as $$declare c jsonb;j json;act text;actor uuid:=auth.uid();r text;actor_name text;x public.forms;y public.form_responses;old workforce_private.form_operations;keys text[];new_answers jsonb;stamp timestamptz:=clock_timestamp();result jsonb;personal boolean;max_history integer;begin
 if t is null or o is null then raise exception using errcode='22023',message='Invalid form operation identity';end if;
 if actor is null or workforce_private.membership_role(t)is null then raise exception using errcode='42501',message='Forms unavailable';end if;
 if raw_change is null or octet_length(raw_change)+256>262144 then raise exception using errcode='22023',message='Form request too large';end if;
 j:=raw_change::json;if octet_length((j->'schema')::text)>131072 or octet_length((j->'answers')::text)>65536 then raise exception using errcode='22023',message='Form schema or answers too large';end if;if not workforce_private.forms_json_unique(j)then raise exception using errcode='22023',message='Duplicate form properties';end if;c:=j::jsonb;
 if jsonb_typeof(c)is distinct from'object'or octet_length(c::text)+256>262144 then raise exception using errcode='22023',message='Invalid form command';end if;act:=c->>'action';personal:=act in('save_progress','submit_response','edit_response');
 keys:=case act when'create_form'then array['action','allowRespondentEdit','audienceIds','description','name','schema']when'edit_form'then array['action','allowRespondentEdit','description','formId','formRevision','name','schema']when'set_audience'then array['action','audienceIds','formId','formRevision']when'publish_form'then array['action','formId','formRevision']when'archive_form'then array['action','formId','formRevision']when'restore_form'then array['action','formId','formRevision']when'save_progress'then array['action','answers','formId','formRevision','responseRevision']when'submit_response'then array['action','answers','formId','formRevision','responseRevision']when'edit_response'then array['action','answers','formId','formRevision','responseRevision']when'admin_edit_response'then array['action','answers','formId','formRevision','responseId','responseRevision']when'review_response'then array['action','formId','formRevision','responseId','responseRevision','reviewed']end;
 if keys is null or(select array_agg(key order by key)from jsonb_object_keys(c)key)is distinct from keys then raise exception using errcode='22023',message='Unknown form command properties';end if;
 if exists(select 1 from jsonb_each(c)where key in('formId','responseId')and not workforce_private.knowledge_uuid(value))or exists(select 1 from jsonb_each(c)where key in('formRevision','responseRevision')and(jsonb_typeof(value)is distinct from'number'or(value#>>'{}')!~'^(0|[1-9][0-9]{0,9})$'or(value#>>'{}')::numeric>2147483647 or key='formRevision'and(value#>>'{}')='0'))then raise exception using errcode='22023',message='Invalid form revision or identity';end if;
 if not personal and workforce_private.membership_role(t)not in('owner','admin')then raise exception using errcode='42501',message='Form management unavailable';end if;
 perform workforce_private.forms_locks(t,actor,o,act in('edit_response','admin_edit_response'));
 perform 1 from public.tenants where id=t for share;perform 1 from auth.users where id=actor for share;perform 1 from public.tenant_memberships where tenant_id=t and user_id=actor for share;r:=workforce_private.membership_role(t);select display_name into actor_name from public.tenant_memberships where tenant_id=t and user_id=actor;
 if r is null or not personal and r not in('owner','admin')then raise exception using errcode='42501',message='Forms unavailable';end if;
 if act<>'create_form'then select *into x from public.forms where tenant_id=t and id=(c->>'formId')::uuid for update;if not found or personal and workforce_private.forms_reader(t,x.id) is distinct from true then raise exception using errcode='42501',message='Form unavailable';end if;end if;
 select *into old from workforce_private.form_operations where tenant_id=t and actor_id=actor and operation_id=o;
 if found then if old.state='closed_absent'then if old.action<>act then raise exception using errcode='22023',message='Operation UUID bound to another action';end if;raise exception using errcode='40001',message='Operation was durably reconciled absent; choose a new operation';end if;if old.payload_hash is distinct from encode(sha256(convert_to(c::text,'UTF8')),'hex') then raise exception using errcode='22023',message='Operation UUID bound to another form command';end if;if workforce_private.forms_access(t,old.form_id,case when personal then'mine'else'manage'end) is distinct from true then raise exception using errcode='42501',message='Form receipt unavailable';end if;return old.result||jsonb_build_object('role',r);end if;
 if act<>'create_form'and x.revision<>(c->>'formRevision')::integer then raise exception using errcode='40001',message='Form changed; refresh and review';end if;
 if act in('create_form','edit_form')then if workforce_private.forms_name_valid(c)is distinct from true or jsonb_typeof(c->'allowRespondentEdit')is distinct from'boolean'or not workforce_private.forms_schema_valid(c->'schema')then raise exception using errcode='22023',message='Invalid form details or schema';end if;end if;
 if act in('create_form','set_audience')then if jsonb_typeof(c->'audienceIds')is distinct from'array'or exists(select 1 from jsonb_array_elements(c->'audienceIds')v where not workforce_private.knowledge_uuid(v))then raise exception using errcode='22023',message='Invalid audience identity';end if;perform workforce_private.forms_lock_audience(t,c->'audienceIds');if not workforce_private.forms_audience_valid(t,c->'audienceIds')then raise exception using errcode='22023',message='Choose eligible form recipients';end if;end if;
 stamp:=clock_timestamp();
 if act='create_form'then insert into public.forms(tenant_id,name,description,schema,allow_respondent_edit)values(t,c->>'name',c->>'description',workforce_private.forms_schema_canonical(c->'schema'),(c->>'allowRespondentEdit')::boolean)returning *into x;
 elsif act='edit_form'then if x.status='archived'then raise exception using errcode='40001',message='Archived forms are read only';end if;if x.schema_frozen and x.schema is distinct from workforce_private.forms_schema_canonical(c->'schema')then raise exception using errcode='40001',message='Published schema is immutable';end if;if x.revision=2147483647 then raise exception using errcode='40001',message='Form revision limit reached';end if;update public.forms set name=c->>'name',description=c->>'description',schema=workforce_private.forms_schema_canonical(c->'schema'),allow_respondent_edit=(c->>'allowRespondentEdit')::boolean,revision=revision+1,updated_at=stamp where id=x.id returning *into x;
 elsif act='set_audience'then if x.status='archived'or x.revision=2147483647 then raise exception using errcode='40001',message='Form assignment cannot change';end if;delete from public.form_assignments where tenant_id=t and form_id=x.id;update public.forms set revision=revision+1,updated_at=stamp where id=x.id returning *into x;
 elsif act='publish_form'then perform workforce_private.forms_lock_audience(t,(select coalesce(jsonb_agg(to_jsonb(actor_id)),'[]')from public.form_assignments where tenant_id=t and form_id=x.id));if x.status<>'draft'or x.revision=2147483647 or not exists(select 1 from jsonb_array_elements(x.schema)f where f->>'kind'<>'description')or not exists(select 1 from public.form_assignments where tenant_id=t and form_id=x.id)or exists(select 1 from public.form_assignments a where a.tenant_id=t and a.form_id=x.id and not workforce_private.forms_eligible(t,a.actor_id))then raise exception using errcode='40001',message='Publication requires answerable fields and eligible recipients';end if;update public.forms set status='published',schema_frozen=true,revision=revision+1,updated_at=stamp where id=x.id returning *into x;
 elsif act='archive_form'then if x.status='archived'or x.revision=2147483647 then raise exception using errcode='40001',message='Form cannot archive';end if;update public.forms set restore_status=status,status='archived',revision=revision+1,updated_at=stamp where id=x.id returning *into x;
 elsif act='restore_form'then if x.status<>'archived'or x.restore_status is null or x.revision=2147483647 then raise exception using errcode='40001',message='Form cannot restore';end if;update public.forms set status=restore_status,restore_status=null,revision=revision+1,updated_at=stamp where id=x.id returning *into x;
 else
  if x.status<>'published'then raise exception using errcode='40001',message='Only published forms accept response changes';end if;
  if personal then select *into y from public.form_responses where tenant_id=t and form_id=x.id and actor_id=actor for update;else select *into y from public.form_responses where tenant_id=t and form_id=x.id and id=(c->>'responseId')::uuid and status='submitted'for update;if not found then raise exception using errcode='42501',message='Submitted response unavailable';end if;end if;
  if coalesce(y.revision,0)<>(c->>'responseRevision')::integer then raise exception using errcode='40001',message='Response changed; refresh and review';end if;if y.revision=2147483647 then raise exception using errcode='40001',message='Response revision limit reached';end if;
  stamp:=clock_timestamp();
  if act='save_progress'and y.status='submitted'or act='submit_response'and y.status='submitted'or act='edit_response'and(y.status is distinct from'submitted'or not x.allow_respondent_edit)then raise exception using errcode='40001',message='Response action unavailable';end if;
  if act='review_response'then if jsonb_typeof(c->'reviewed')is distinct from'boolean'then raise exception using errcode='22023',message='Invalid review command';end if;update public.form_responses set reviewed=(c->>'reviewed')::boolean,reviewed_at=case when(c->>'reviewed')::boolean then stamp else null end,reviewed_by=case when(c->>'reviewed')::boolean then actor else null end,reviewer_name=case when(c->>'reviewed')::boolean then actor_name else null end,revision=revision+1,updated_at=stamp where id=y.id returning *into y;
  else
   new_answers:=workforce_private.forms_answers_canonical(x.schema,c->'answers');if not workforce_private.forms_answers_valid(x.schema,new_answers,act<>'save_progress')then raise exception using errcode='22023',message='Answers do not satisfy the form';end if;
