    insert into workforce_private.form_response_history(tenant_id,response_id,revision,answers,status,submitted_at,updated_at,last_edited_by,last_editor_name,last_edited_at,reviewed,reviewed_at,reviewed_by,reviewer_name)values(t,y.id,y.revision,y.answers,y.status,y.submitted_at,y.updated_at,y.last_edited_by,y.last_editor_name,y.last_edited_at,y.reviewed,y.reviewed_at,y.reviewed_by,y.reviewer_name);update workforce_private.form_history_counter set retained_rows=retained_rows+1 where form_history_counter.id;
   end if;
   if y.id is null then insert into public.form_responses(tenant_id,form_id,actor_id,author_name,answers,schema,form_name,status,submitted_at,last_edited_by,last_editor_name,updated_at,last_edited_at)values(t,x.id,actor,actor_name,new_answers,x.schema,x.name,case when act='submit_response'then'submitted'else'in_progress'end,case when act='submit_response'then stamp else null end,actor,actor_name,stamp,stamp)returning *into y;
   else update public.form_responses set answers=new_answers,schema=x.schema,form_name=case when submitted_at is null then x.name else form_name end,status=case when act='save_progress'then'in_progress'else'submitted'end,submitted_at=case when act='save_progress'then null else coalesce(submitted_at,stamp)end,last_edited_by=actor,last_editor_name=actor_name,last_edited_at=stamp,updated_at=stamp,reviewed=false,reviewed_at=null,reviewed_by=null,reviewer_name=null,revision=revision+1,content_edits=content_edits+case when act in('edit_response','admin_edit_response')then 1 else 0 end where id=y.id returning *into y;end if;
  end if;
 end if;
 if act in('create_form','set_audience')then insert into public.form_assignments(tenant_id,form_id,actor_id,name)select t,x.id,(v#>>'{}')::uuid,m.display_name from jsonb_array_elements(c->'audienceIds')v join public.tenant_memberships m on m.tenant_id=t and m.user_id=(v#>>'{}')::uuid;end if;
 result:=jsonb_build_object('tenantId',t,'actorId',actor,'role',r,'operationId',o,'action',act,'formId',x.id,'formRevision',x.revision,'updatedAt',workforce_private.forms_time(case when y.id is not null then y.updated_at else x.updated_at end));if y.id is not null then result:=result||jsonb_build_object('responseId',y.id,'responseRevision',y.revision,'responseStatus',y.status,'submittedAt',workforce_private.forms_time(y.submitted_at));end if;
 insert into public.form_audit(tenant_id,form_id,response_id,actor_id,actor_name,action,form_revision,response_revision)values(t,x.id,y.id,actor,actor_name,act,x.revision,y.revision);
