create function public.save_form(target_tenant uuid,operation_id uuid,change_text text)returns jsonb language sql security invoker set search_path=''as $$select workforce_private.save_form(target_tenant,operation_id,change_text)$$;
create function workforce_private.reconcile_form_operation(t uuid,o uuid,act text)returns jsonb language plpgsql security definer set search_path=''as $$declare a uuid:=auth.uid();r text;receipt workforce_private.form_operations;personal boolean:=act in('save_progress','submit_response','edit_response');begin
 if t is null or o is null then raise exception using errcode='22023',message='Invalid form recovery identity';end if;
 if act is null or act not in('create_form','edit_form','set_audience','publish_form','archive_form','restore_form','save_progress','submit_response','edit_response','admin_edit_response','review_response')or a is null or workforce_private.membership_role(t)is null then raise exception using errcode='42501',message='Form recovery unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended(a::text||':'||o::text,63));r:=workforce_private.membership_role(t);if r is null or not personal and r not in('owner','admin')then raise exception using errcode='42501',message='Form recovery unavailable';end if;
 select *into receipt from workforce_private.form_operations where tenant_id=t and actor_id=a and operation_id=o;
 if found then if receipt.action<>act then raise exception using errcode='22023',message='Recovery action differs from operation';end if;if receipt.state='recorded'and workforce_private.forms_access(t,receipt.form_id,case when personal then'mine'else'manage'end) is distinct from true then raise exception using errcode='42501',message='Form recovery unavailable';end if;
 else insert into workforce_private.form_operations(tenant_id,actor_id,operation_id,action,state)values(t,a,o,act,'closed_absent')returning *into receipt;end if;
 return jsonb_build_object('tenantId',t,'actorId',a,'role',r,'operationId',o,'action',act,'status',case when receipt.state='closed_absent'then'not_recorded'else'recorded'end,'saved',case when receipt.state='closed_absent'then null else receipt.result||jsonb_build_object('role',r)end);end$$;
create function public.reconcile_form_operation(target_tenant uuid,operation_id uuid,action_name text)returns jsonb language sql volatile security invoker set search_path=''as $$select workforce_private.reconcile_form_operation(target_tenant,operation_id,action_name)$$;
create function workforce_private.forms_version(t uuid,mode text,f uuid default null)returns text language plpgsql stable security definer set search_path=''as $$begin
 if workforce_private.membership_role(t)is null or mode='manage'and workforce_private.membership_role(t)not in('owner','admin')then raise exception using errcode='42501',message='Forms unavailable';end if;
 return md5(jsonb_build_array((select coalesce(jsonb_agg(jsonb_build_array(x.id,x.revision,x.status,(select coalesce(jsonb_agg(jsonb_build_array(a.actor_id,workforce_private.forms_eligible(t,a.actor_id))order by a.actor_id),'[]')from public.form_assignments a where a.tenant_id=t and a.form_id=x.id))order by x.id),'[]')from public.forms x where x.tenant_id=t and(f is null or x.id=f)and(mode='manage'or workforce_private.forms_reader(t,x.id))),(select coalesce(jsonb_agg(jsonb_build_array(y.id,y.revision,y.status)order by y.id),'[]')from public.form_responses y where y.tenant_id=t and(f is null or y.form_id=f)and(mode='manage'and y.status='submitted'or mode='mine'and y.actor_id=auth.uid()and workforce_private.forms_reader(t,y.form_id))),(select retained_rows<4096 from workforce_private.form_history_counter where form_history_counter.id),(select jsonb_build_array(name,time_zone)from public.tenants where id=t))::text);
end$$;
create function workforce_private.forms_roster_version(t uuid)returns text language plpgsql stable security definer set search_path=''as $$begin if workforce_private.membership_role(t)not in('owner','admin')or workforce_private.membership_role(t)is null then raise exception using errcode='42501',message='Form roster unavailable';end if;return md5((select coalesce(jsonb_agg(jsonb_build_array(m.user_id,m.display_name,m.status,a.email_confirmed_at,a.is_anonymous)order by m.user_id),'[]')from public.tenant_memberships m join auth.users a on a.id=m.user_id where m.tenant_id=t)::text);end$$;
create function workforce_private.forms_response_json(t uuid,id uuid,mode text,include_answers boolean default false)returns jsonb language plpgsql stable security definer set search_path=''as $$declare y public.form_responses;x public.forms;can_edit boolean;res jsonb;begin
 select *into y from public.form_responses where tenant_id=t and form_responses.id=forms_response_json.id;if not found then raise exception using errcode='42501',message='Response unavailable';end if;
 if mode='manage'then if workforce_private.membership_role(t)not in('owner','admin')or workforce_private.membership_role(t)is null or y.status<>'submitted'then raise exception using errcode='42501',message='Submitted response unavailable';end if;
 elsif mode is distinct from'mine'or y.actor_id is distinct from auth.uid()or workforce_private.forms_reader(t,y.form_id) is distinct from true then raise exception using errcode='42501',message='Own response unavailable';end if;
 select *into x from public.forms where tenant_id=t and forms.id=y.form_id;can_edit:=x.status='published'and y.status='submitted'and y.revision<2147483647 and y.content_edits<50 and(select retained_rows<4096 from workforce_private.form_history_counter where form_history_counter.id)and(mode='manage'or x.allow_respondent_edit);
 res:=jsonb_build_object('id',y.id,'formId',y.form_id,'actorId',y.actor_id,'authorName',y.author_name,'revision',y.revision,'status',y.status,'submittedAt',workforce_private.forms_time(y.submitted_at),'updatedAt',workforce_private.forms_time(y.updated_at),'lastEditedBy',y.last_edited_by,'lastEditorName',y.last_editor_name,'lastEditedAt',workforce_private.forms_time(y.last_edited_at),'reviewed',y.reviewed,'reviewedAt',workforce_private.forms_time(y.reviewed_at),'reviewedBy',y.reviewed_by,'reviewerName',y.reviewer_name,'canEdit',can_edit,'canReview',mode='manage'and x.status='published'and y.revision<2147483647);
 if include_answers then res:=res||jsonb_build_object('answers',y.answers,'schema',y.schema,'formName',y.form_name);end if;return res;
