create function workforce_private.forms_form_json(t uuid,id uuid,mode text)returns jsonb language plpgsql stable security definer set search_path=''as $$declare x public.forms;y public.form_responses;mine boolean;own jsonb:=null;begin
 if workforce_private.forms_access(t,id,mode) is distinct from true then raise exception using errcode='42501',message='Form unavailable';end if;select *into x from public.forms where tenant_id=t and forms.id=forms_form_json.id;mine:=exists(select 1 from public.form_assignments where tenant_id=t and form_id=forms_form_json.id and actor_id=auth.uid());
 if mode='mine'then select *into y from public.form_responses where tenant_id=t and form_id=forms_form_json.id and actor_id=auth.uid();if found then own:=jsonb_build_object('id',y.id,'revision',y.revision,'status',y.status,'submittedAt',workforce_private.forms_time(y.submitted_at),'updatedAt',workforce_private.forms_time(y.updated_at));end if;end if;
 return jsonb_build_object('id',x.id,'name',x.name,'description',x.description,'status',x.status,'restoreStatus',x.restore_status,'revision',x.revision,'schemaFrozen',x.schema_frozen,'allowRespondentEdit',x.allow_respondent_edit,'isAssigned',mine,'audienceCount',case when mode='manage'then(select count(*)from public.form_assignments where tenant_id=t and form_id=forms_form_json.id)else null end,'eligibleAudienceCount',case when mode='manage'then(select count(*)from public.form_assignments a where a.tenant_id=t and a.form_id=forms_form_json.id and workforce_private.forms_eligible(t,a.actor_id))else null end,'createdAt',workforce_private.forms_time(x.created_at),'updatedAt',workforce_private.forms_time(x.updated_at),'ownResponse',own,'capabilities',jsonb_build_object('canEdit',mode='manage'and x.status<>'archived'and x.revision<2147483647,'canPublish',mode='manage'and x.status='draft'and x.revision<2147483647 and exists(select 1 from public.form_assignments where tenant_id=t and form_id=forms_form_json.id)and exists(select 1 from jsonb_array_elements(x.schema)f where f->>'kind'<>'description')and not exists(select 1 from public.form_assignments a where a.tenant_id=t and a.form_id=forms_form_json.id and not workforce_private.forms_eligible(t,a.actor_id)),'canArchive',mode='manage'and x.status<>'archived'and x.revision<2147483647,'canRestore',mode='manage'and x.status='archived'and x.revision<2147483647,'canSaveProgress',mode='mine'and mine and y.status is distinct from'submitted'and coalesce(y.revision,0)<2147483647,'canSubmit',mode='mine'and mine and y.status is distinct from'submitted'and coalesce(y.revision,0)<2147483647,'canEditResponse',mode='mine'and mine and coalesce(y.status='submitted',false)and x.allow_respondent_edit and y.revision<2147483647 and y.content_edits<50 and(select retained_rows<4096 from workforce_private.form_history_counter where form_history_counter.id),'canViewResponses',mode='manage'));
end$$;
create function workforce_private.forms_roster(t uuid,q text,n integer,after_key text default null,after_id uuid default null)returns jsonb language plpgsql stable security definer set search_path=''as $$declare rows jsonb;next_item jsonb;total bigint;begin
 if workforce_private.membership_role(t)is null or workforce_private.membership_role(t)not in('owner','admin')then raise exception using errcode='42501',message='Form roster unavailable';end if;
 select count(*)into total from public.tenant_memberships m join auth.users a on a.id=m.user_id where m.tenant_id=t and m.status='active'and a.email_confirmed_at is not null and a.is_anonymous is not true and strpos(lower(m.display_name),lower(q))>0;
 with eligible as(select m.user_id,m.display_name,lower(m.display_name)k from public.tenant_memberships m join auth.users a on a.id=m.user_id where m.tenant_id=t and m.status='active'and a.email_confirmed_at is not null and a.is_anonymous is not true and strpos(lower(m.display_name),lower(q))>0 and(after_id is null or(lower(m.display_name),m.user_id)>(after_key,after_id))order by lower(m.display_name),m.user_id limit n+1),page as(select *from eligible order by k,user_id limit n)
 select coalesce((select jsonb_agg(jsonb_build_object('actorId',user_id,'name',display_name,'eligible',true)order by k,user_id)from page),'[]'),case when(select count(*)from eligible)>n then(select jsonb_build_object('id',user_id,'key',k)from page order by k desc,user_id desc limit 1)else null end into rows,next_item;
 return jsonb_build_object('users',rows,'matchedCount',total,'position',next_item);end$$;
create function workforce_private.forms_history(t uuid,f uuid,r uuid,n integer,after_revision integer default null)returns jsonb language plpgsql stable security definer set search_path=''as $$declare rows jsonb;next_item jsonb;y public.form_responses;total bigint;begin
 if n is null or n not between 1 and 10 then raise exception using errcode='22023',message='History page must contain 1 to 10 records';end if;
 if workforce_private.membership_role(t)is null or workforce_private.membership_role(t)not in('owner','admin')then raise exception using errcode='42501',message='Response history unavailable';end if;select *into y from public.form_responses where tenant_id=t and form_id=f and id=r and status='submitted';if not found then raise exception using errcode='42501',message='Submitted response unavailable';end if;
 select count(*)into total from workforce_private.form_response_history where tenant_id=t and response_id=r;
 with available as(select *from workforce_private.form_response_history where tenant_id=t and response_id=r and(after_revision is null or revision<after_revision)order by revision desc limit n+1),page as(select *from available order by revision desc limit n)
 select coalesce((select jsonb_agg(jsonb_build_object('id',id,'responseId',response_id,'revision',revision,'answers',answers,'formName',y.form_name,'status',status,'submittedAt',workforce_private.forms_time(submitted_at),'updatedAt',workforce_private.forms_time(updated_at),'lastEditedBy',last_edited_by,'lastEditorName',last_editor_name,'lastEditedAt',workforce_private.forms_time(last_edited_at),'reviewed',reviewed,'reviewedAt',workforce_private.forms_time(reviewed_at),'reviewedBy',reviewed_by,'reviewerName',reviewer_name,'retainedAt',workforce_private.forms_time(retained_at))order by revision desc)from page),'[]'),case when(select count(*)from available)>n then(select jsonb_build_object('id',id,'key',revision::text)from page order by revision limit 1)else null end into rows,next_item;
 return jsonb_build_object('history',rows,'historyCount',total,'position',next_item);end$$;
create function workforce_private.forms_assignees(t uuid,f uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$begin
 if workforce_private.forms_access(t,f,'manage') is distinct from true then raise exception using errcode='42501',message='Form audience unavailable';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('actorId',a.actor_id,'name',a.name,'eligible',workforce_private.forms_eligible(t,a.actor_id))order by a.actor_id),'[]')from public.form_assignments a where a.tenant_id=t and a.form_id=f);end$$;
create function workforce_private.forms_time(v timestamptz)returns text language sql immutable security invoker set search_path=''as $$select to_char(v at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')$$;
create function workforce_private.forms_position_valid(t uuid,kind text,f uuid,r uuid,id uuid,key text,q text)returns boolean language plpgsql stable security definer set search_path=''as $$begin
 if workforce_private.membership_role(t)is null or workforce_private.membership_role(t)not in('owner','admin')then return false;end if;
 if kind='roster'then return exists(select 1 from public.tenant_memberships m join auth.users a on a.id=m.user_id where m.tenant_id=t and m.user_id=forms_position_valid.id and lower(m.display_name)=key and strpos(lower(m.display_name),lower(q))>0 and m.status='active'and a.email_confirmed_at is not null and a.is_anonymous is not true);
 elsif kind='response'then return exists(select 1 from workforce_private.form_response_history h join public.form_responses y on y.tenant_id=h.tenant_id and y.id=h.response_id where y.tenant_id=t and y.form_id=f and y.id=r and y.status='submitted'and h.id=forms_position_valid.id and h.revision::text=key);end if;return false;end$$;
create function public.read_forms(target_tenant uuid,read_kind text default'catalog',read_view text default'mine',target_form uuid default null,target_response uuid default null,status_filter text default'all',review_filter text default'all',search_text text default'',page_limit integer default 50,after_item jsonb default null)returns jsonb language plpgsql stable security invoker set search_path=''as $$declare r text:=workforce_private.membership_role(target_tenant);identity jsonb;scope jsonb;version text;rows jsonb;counts jsonb;position jsonb:=null;extra jsonb;res jsonb;x public.forms;y public.form_responses;cursor_key text;cursor_id uuid;begin
 if r is null or read_view is null or read_kind is null or read_view not in('mine','manage')or read_kind not in('catalog','form','roster','responses','response')or read_view='manage'and r not in('owner','admin')or read_kind in('roster','responses','response')and(read_view<>'manage'or r not in('owner','admin'))then raise exception using errcode='42501',message='Forms unavailable';end if;
 if page_limit is null or page_limit not between 1 and(case when read_kind='response'then 10 else 100 end)or search_text is null or workforce_private.knowledge_utf16(search_text)>100 or octet_length(search_text)>512 or review_filter is null or status_filter is null or review_filter not in('all','reviewed','not_reviewed')or read_kind='catalog'and status_filter not in('all','draft','published','archived')or read_kind='responses'and status_filter not in('all','submitted')then raise exception using errcode='22023',message='Invalid Forms query';end if;
 if read_kind in('catalog','roster')and target_form is not null or read_kind<>'response'and target_response is not null or read_kind<>'responses'and review_filter<>'all'or read_kind in('form','roster','response')and status_filter<>'all'or read_kind in('form','response')and search_text<>''or read_kind='form'and after_item is not null then raise exception using errcode='22023',message='Unsupported Forms query';end if;
 if read_kind in('form','responses','response')then if workforce_private.forms_access(target_tenant,target_form,read_view) is distinct from true then raise exception using errcode='42501',message='Form unavailable';end if;select *into x from public.forms where tenant_id=target_tenant and forms.id=target_form;end if;
 if read_kind='response'then select *into y from public.form_responses where tenant_id=target_tenant and form_id=target_form and form_responses.id=target_response and status='submitted';if not found then raise exception using errcode='42501',message='Submitted response unavailable';end if;end if;
 version:=case when read_kind='roster'then workforce_private.forms_roster_version(target_tenant)else workforce_private.forms_version(target_tenant,read_view,case when read_kind='catalog'then null else target_form end)end;
 identity:=jsonb_build_object('tenantId',target_tenant,'actorId',auth.uid(),'role',r);scope:=identity||jsonb_build_object('kind',read_kind,'view',read_view,'formId',target_form,'responseId',target_response,'status',status_filter,'review',review_filter,'search',search_text,'version',version);
 if after_item is not null then
  if jsonb_typeof(after_item)is distinct from'object'or(select array_agg(k order by k)from jsonb_object_keys(after_item)k)is distinct from array['position','scope']or jsonb_typeof(after_item->'position')is distinct from'object'or(select array_agg(k order by k)from jsonb_object_keys(after_item->'position')k)is distinct from array['id','key']or not workforce_private.knowledge_uuid(after_item->'position'->'id')or jsonb_typeof(after_item->'position'->'key')is distinct from'string'or workforce_private.knowledge_utf16(after_item->'position'->>'key')>200 then raise exception using errcode='22023',message='Invalid Forms cursor';end if;
  if after_item->'scope'is distinct from scope then raise exception using errcode='40001',message='Forms scope or collection changed';end if;cursor_id:=(after_item->'position'->>'id')::uuid;cursor_key:=after_item->'position'->>'key';
 end if;
