 if read_kind='catalog'then
  with visible as(select *from public.forms f where f.tenant_id=target_tenant and(read_view='manage'or workforce_private.forms_reader(target_tenant,f.id))and strpos(lower(f.name),lower(search_text))>0)
  select jsonb_build_object('total',count(*),'draft',count(*)filter(where status='draft'),'published',count(*)filter(where status='published'),'archived',count(*)filter(where status='archived'))into counts from visible;
  if cursor_id is not null and not exists(select 1 from public.forms f where f.tenant_id=target_tenant and f.id=cursor_id and f.created_at=cursor_key::timestamptz and(read_view='manage'or workforce_private.forms_reader(target_tenant,f.id))and(status_filter='all'or f.status=status_filter)and strpos(lower(f.name),lower(search_text))>0)then raise exception using errcode='40001',message='Forms cursor changed';end if;
  with available as(select *from public.forms f where f.tenant_id=target_tenant and(read_view='manage'or workforce_private.forms_reader(target_tenant,f.id))and(status_filter='all'or f.status=status_filter)and strpos(lower(f.name),lower(search_text))>0 and(cursor_id is null or(f.created_at,f.id)<(cursor_key::timestamptz,cursor_id))order by created_at desc,f.id desc limit page_limit+1),page as(select *from available order by created_at desc,id desc limit page_limit)
