  res:=res||jsonb_build_object('view',read_view,'company',(select jsonb_build_object('id',t.id,'name',name,'time_zone',time_zone)from public.tenants t where t.id=target_tenant),'forms',rows,'counts',counts,'catalogVersion',version,'capabilities',jsonb_build_object('canManage',r in('owner','admin')));
 elsif read_kind='form'then
  res:=res||jsonb_build_object('view',read_view,'company',(select jsonb_build_object('id',t.id,'name',name,'time_zone',time_zone)from public.tenants t where t.id=target_tenant),'form',workforce_private.forms_form_json(target_tenant,target_form,read_view),'schema',x.schema,'collectionVersion',version);
  if read_view='mine'then select *into y from public.form_responses where tenant_id=target_tenant and form_id=target_form and actor_id=auth.uid();res:=res||jsonb_build_object('response',case when y.id is not null then workforce_private.forms_response_json(target_tenant,y.id,'mine',true)else null end);
