 elsif read_kind='roster'then if cursor_id is not null and not workforce_private.forms_position_valid(target_tenant,'roster',null,null,cursor_id,cursor_key,search_text)then raise exception using errcode='40001',message='Roster cursor changed';end if;extra:=workforce_private.forms_roster(target_tenant,search_text,page_limit,cursor_key,cursor_id);position:=extra->'position';res:=res||(extra-'position')||jsonb_build_object('rosterVersion',version);
 elsif read_kind='responses'then
  select jsonb_build_object('total',count(*),'reviewed',count(*)filter(where reviewed),'notReviewed',count(*)filter(where not reviewed))into counts from public.form_responses z where z.tenant_id=target_tenant and z.form_id=target_form and z.status='submitted'and strpos(lower(z.author_name),lower(search_text))>0;
  if cursor_id is not null and not exists(select 1 from public.form_responses z where z.tenant_id=target_tenant and z.form_id=target_form and z.id=cursor_id and z.status='submitted'and z.submitted_at=cursor_key::timestamptz and strpos(lower(z.author_name),lower(search_text))>0 and(review_filter='all'or review_filter='reviewed'and z.reviewed or review_filter='not_reviewed'and not z.reviewed))then raise exception using errcode='40001',message='Response cursor changed';end if;
  with available as(select *from public.form_responses z where z.tenant_id=target_tenant and z.form_id=target_form and z.status='submitted'and strpos(lower(z.author_name),lower(search_text))>0 and(review_filter='all'or review_filter='reviewed'and z.reviewed or review_filter='not_reviewed'and not z.reviewed)and(cursor_id is null or(z.submitted_at,z.id)<(cursor_key::timestamptz,cursor_id))order by submitted_at desc,z.id desc limit page_limit+1),page as(select *from available order by submitted_at desc,id desc limit page_limit)
  select coalesce((select jsonb_agg(workforce_private.forms_response_json(target_tenant,p.id,'manage')order by submitted_at desc,p.id desc)from page p),'[]'),case when(select count(*)from available)>page_limit then(select jsonb_build_object('id',p.id,'key',workforce_private.forms_time(submitted_at))from page p order by submitted_at,p.id limit 1)else null end into rows,position;
  res:=res||jsonb_build_object('form',workforce_private.forms_form_json(target_tenant,target_form,'manage'),'responses',rows,'counts',counts,'collectionVersion',version);
 else
  if cursor_id is not null and(cursor_key!~'^[1-9][0-9]{0,9}$'or cursor_key::numeric>2147483647 or not workforce_private.forms_position_valid(target_tenant,'response',target_form,target_response,cursor_id,cursor_key,''))then raise exception using errcode='22023',message='Invalid response history cursor';end if;
  extra:=workforce_private.forms_history(target_tenant,target_form,target_response,page_limit,case when cursor_id is null then null else cursor_key::integer end);position:=extra->'position';res:=res||(extra-'position')||jsonb_build_object('form',workforce_private.forms_form_json(target_tenant,target_form,'manage'),'response',workforce_private.forms_response_json(target_tenant,target_response,'manage',true),'collectionVersion',version);
 end if;
 return res||jsonb_build_object('nextCursor',case when position is null or position='null'::jsonb then null else jsonb_build_object('scope',scope,'position',position)end);
end$$;
create function public.read_forms_access(target_tenant uuid,read_kind text default'catalog',read_view text default'mine',target_form uuid default null,target_response uuid default null)returns jsonb language plpgsql stable security invoker set search_path=''as $$declare r text:=workforce_private.membership_role(target_tenant);x public.forms;y public.form_responses;begin
 if r is null or read_view is null or read_kind is null or read_view not in('mine','manage')or read_kind not in('catalog','form','roster','responses','response')or read_view='manage'and r not in('owner','admin')or read_kind in('roster','responses','response')and(read_view<>'manage'or r not in('owner','admin'))then raise exception using errcode='42501',message='Forms unavailable';end if;
 if read_kind in('form','responses','response')then if workforce_private.forms_access(target_tenant,target_form,read_view) is distinct from true then raise exception using errcode='42501',message='Form unavailable';end if;select *into x from public.forms where tenant_id=target_tenant and id=target_form;end if;
 if read_kind='response'then select *into y from public.form_responses where tenant_id=target_tenant and form_id=target_form and id=target_response and status='submitted';if not found then raise exception using errcode='42501',message='Submitted response unavailable';end if;end if;
 return jsonb_build_object('tenantId',target_tenant,'actorId',auth.uid(),'role',r,'view',read_view,'collectionVersion',case when read_kind='roster'then workforce_private.forms_roster_version(target_tenant)else workforce_private.forms_version(target_tenant,read_view,case when read_kind='catalog'then null else target_form end)end,'formRevision',x.revision,'responseRevision',y.revision);end$$;
-- Explicit default-ACL defense on every new helper/RPC; no baseline ACL is changed.
do $$declare fn record;begin
 for fn in select p.oid::regprocedure f from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','workforce_private')and(p.proname like'forms\_%'escape'\'or p.proname in('save_form','reconcile_form_operation','read_forms','read_forms_access'))loop execute format('revoke all on function %s from public,anon,authenticated,service_role',fn.f);end loop;
 for fn in select p.oid::regprocedure f from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('save_form','reconcile_form_operation','read_forms','read_forms_access')or n.nspname='workforce_private'and p.proname in('forms_reader','forms_access','forms_assignees','forms_version','forms_roster_version','forms_form_json','forms_response_json','forms_roster','forms_history','forms_time','forms_position_valid','save_form','reconcile_form_operation')loop execute format('grant execute on function %s to authenticated',fn.f);end loop;
end$$;
